package ru.ultimavox.itsm.platform.security;
import java.util.*; import java.util.stream.*; import org.springframework.core.convert.converter.Converter; import org.springframework.security.authentication.AbstractAuthenticationToken; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.oauth2.jwt.Jwt;
/** Maps Keycloak realm roles to ROLE_* authorities while retaining standard OAuth scope authorities. */
final class KeycloakJwtAuthenticationConverter implements Converter<Jwt, AbstractAuthenticationToken> {
 @Override public AbstractAuthenticationToken convert(Jwt jwt) { Set<GrantedAuthority> authorities=new HashSet<>(); Optional.ofNullable(jwt.getClaimAsString("scope")).stream().flatMap(scope->Arrays.stream(scope.split(" "))).filter(s->!s.isBlank()).map(scope->new SimpleGrantedAuthority("SCOPE_"+scope)).forEach(authorities::add); Map<String,Object> realm=jwt.getClaimAsMap("realm_access"); if(realm!=null && realm.get("roles") instanceof Collection<?> roles) roles.stream().filter(String.class::isInstance).map(String.class::cast).map(role->new SimpleGrantedAuthority("ROLE_"+role)).forEach(authorities::add); return new UsernamePasswordAuthenticationToken(jwt, "N/A", authorities); }
}
